CREATE TABLE public.email_bundles(account_id uuid PRIMARY KEY REFERENCES public.accounts(id),plan text NOT NULL DEFAULT 'free' CHECK(plan IN ('free','standard','pro')),contact_limit integer NOT NULL DEFAULT 25,email_limit integer DEFAULT 50,monthly_price numeric NOT NULL DEFAULT 0,period_start timestamptz NOT NULL DEFAULT date_trunc('month',now()),period_end timestamptz NOT NULL DEFAULT date_trunc('month',now())+interval '1 month',used integer NOT NULL DEFAULT 0,paid_months integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','past_due','cancelled')),renew boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.email_bundles TO authenticated; GRANT ALL ON public.email_bundles TO service_role; ALTER TABLE public.email_bundles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read email bundle" ON public.email_bundles FOR SELECT TO authenticated USING(public.has_workspace_permission(account_id,'campaigns') OR public.has_workspace_permission(account_id,'billing'));
CREATE TABLE public.email_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES public.accounts(id),name text NOT NULL,subject text NOT NULL DEFAULT '',preheader text NOT NULL DEFAULT '',from_name text NOT NULL DEFAULT '',from_email text NOT NULL DEFAULT '',reply_to text NOT NULL DEFAULT '',list_id uuid REFERENCES public.contact_lists(id),postal_address text NOT NULL DEFAULT '',blocks jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','queued','sending','submitted','paused','cancelled','failed')),schedule_at timestamptz,total integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.email_campaigns TO authenticated; GRANT ALL ON public.email_campaigns TO service_role; ALTER TABLE public.email_campaigns ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read email campaigns" ON public.email_campaigns FOR SELECT TO authenticated USING(public.has_workspace_permission(account_id,'campaigns')); CREATE INDEX ON public.email_campaigns(account_id,created_at DESC);
CREATE TABLE public.email_recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES public.email_campaigns(id),account_id uuid NOT NULL,profile_id uuid REFERENCES public.profiles(id),email text NOT NULL,first_name text,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','accepted','delivered','bounced','complaint','unsubscribed','failed','unconfirmed','suppressed')),token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,provider_id text,last_error text,opened_at timestamptz,clicked_at timestamptz,accepted_at timestamptz,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,email)); GRANT SELECT ON public.email_recipients TO authenticated; GRANT ALL ON public.email_recipients TO service_role; ALTER TABLE public.email_recipients ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read email recipients" ON public.email_recipients FOR SELECT TO authenticated USING(public.has_workspace_permission(account_id,'campaigns')); CREATE INDEX ON public.email_recipients(campaign_id,status); CREATE INDEX ON public.email_recipients(account_id,status);
CREATE TABLE public.email_suppressions(account_id uuid NOT NULL,email text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,email)); GRANT SELECT ON public.email_suppressions TO authenticated; GRANT ALL ON public.email_suppressions TO service_role; ALTER TABLE public.email_suppressions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read email suppressions" ON public.email_suppressions FOR SELECT TO authenticated USING(public.has_workspace_permission(account_id,'suppressions'));
CREATE TABLE public.email_provider_capacity(id boolean PRIMARY KEY DEFAULT true CHECK(id),daily_limit integer NOT NULL DEFAULT 100,used integer NOT NULL DEFAULT 0,day date NOT NULL DEFAULT CURRENT_DATE); GRANT ALL ON public.email_provider_capacity TO service_role; ALTER TABLE public.email_provider_capacity ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.email_event_receipts(event_id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.email_event_receipts TO service_role; ALTER TABLE public.email_event_receipts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.email_activate_bundle(_account uuid,_plan text,_contacts integer,_limit integer,_price numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.email_bundles; charge numeric; BEGIN INSERT INTO public.email_bundles(account_id) VALUES(_account) ON CONFLICT DO NOTHING; SELECT * INTO b FROM public.email_bundles WHERE account_id=_account FOR UPDATE; IF b.plan <> 'free' AND b.status='active' AND b.period_end>now() THEN RAISE EXCEPTION 'Your paid bundle is already active. Cancel renewal before changing it.'; END IF; IF _plan NOT IN ('standard','pro') OR _price<=0 OR _contacts<500 THEN RAISE EXCEPTION 'Invalid bundle'; END IF; charge:=round(_price*CASE WHEN b.paid_months<3 THEN 0.7 ELSE 1 END,2); PERFORM public.debit_account(_account,charge,NULL,'Email '||_plan||' monthly bundle'); UPDATE public.email_bundles SET plan=_plan,contact_limit=_contacts,email_limit=_limit,monthly_price=_price,period_start=now(),period_end=now()+interval '1 month',used=0,paid_months=b.paid_months+1,status='active',renew=true,updated_at=now() WHERE account_id=_account; END $$; REVOKE ALL ON FUNCTION public.email_activate_bundle(uuid,text,integer,integer,numeric) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_activate_bundle(uuid,text,integer,integer,numeric) TO service_role;
CREATE OR REPLACE FUNCTION public.email_renew_bundles() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.email_bundles; charge numeric; BEGIN FOR b IN SELECT * FROM public.email_bundles WHERE period_end<=now() FOR UPDATE SKIP LOCKED LOOP IF b.plan='free' OR NOT b.renew THEN UPDATE public.email_bundles SET plan='free',contact_limit=25,email_limit=50,monthly_price=0,used=0,period_start=date_trunc('month',now()),period_end=date_trunc('month',now())+interval '1 month',status='active' WHERE account_id=b.account_id; ELSIF b.status='active' THEN BEGIN charge:=round(b.monthly_price*CASE WHEN b.paid_months<3 THEN 0.7 ELSE 1 END,2); PERFORM public.debit_account(b.account_id,charge,NULL,'Email '||b.plan||' monthly renewal'); UPDATE public.email_bundles SET used=0,paid_months=paid_months+1,period_start=now(),period_end=now()+interval '1 month',updated_at=now() WHERE account_id=b.account_id; EXCEPTION WHEN OTHERS THEN UPDATE public.email_bundles SET status='past_due',updated_at=now() WHERE account_id=b.account_id; END; END IF; END LOOP; END $$; REVOKE ALL ON FUNCTION public.email_renew_bundles() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_renew_bundles() TO service_role;
CREATE OR REPLACE FUNCTION public.email_queue_campaign(_id uuid,_account uuid,_schedule timestamptz DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.email_campaigns; b public.email_bundles; count_contacts integer; recipients integer; BEGIN SELECT * INTO c FROM public.email_campaigns WHERE id=_id AND account_id=_account FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; IF c.status<>'draft' THEN RETURN c.total; END IF; IF EXISTS(SELECT 1 FROM public.accounts WHERE id=_account AND (suspended_at IS NOT NULL OR sending_suspended_at IS NOT NULL)) THEN RAISE EXCEPTION 'Sending is on hold for this business'; END IF; IF length(trim(c.subject))=0 OR length(trim(c.from_name))=0 OR length(trim(c.postal_address))<5 OR jsonb_array_length(c.blocks)=0 THEN RAISE EXCEPTION 'Complete subject, sender, address and email design'; END IF; IF NOT EXISTS(SELECT 1 FROM public.email_sending_domains WHERE account_id=_account AND status='verified' AND domain=split_part(lower(c.from_email),'@',2)) THEN RAISE EXCEPTION 'Verify your sender domain before sending'; END IF; IF c.list_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contact_lists WHERE id=c.list_id AND account_id=_account) THEN RAISE EXCEPTION 'List not found'; END IF; INSERT INTO public.email_bundles(account_id) VALUES(_account) ON CONFLICT DO NOTHING; SELECT * INTO b FROM public.email_bundles WHERE account_id=_account FOR UPDATE; IF b.plan='free' AND b.period_end<=now() THEN UPDATE public.email_bundles SET used=0,period_start=date_trunc('month',now()),period_end=date_trunc('month',now())+interval '1 month' WHERE account_id=_account RETURNING * INTO b; END IF; IF b.status<>'active' OR b.period_end<=now() THEN RAISE EXCEPTION 'Your email bundle needs renewal'; END IF; SELECT count(*) INTO count_contacts FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email); IF count_contacts>b.contact_limit THEN RAISE EXCEPTION 'Your contact count exceeds your email bundle. Choose a larger bundle.'; END IF; SELECT count(*) INTO recipients FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email) AND (c.list_id IS NULL OR EXISTS(SELECT 1 FROM public.profile_list_members m WHERE m.list_id=c.list_id AND m.profile_id=p.id)); IF recipients=0 THEN RAISE EXCEPTION 'No subscribed email contacts in this audience'; END IF; IF b.email_limit IS NOT NULL AND b.used+recipients>b.email_limit THEN RAISE EXCEPTION 'Monthly email allowance exceeded'; END IF; INSERT INTO public.email_recipients(campaign_id,account_id,profile_id,email,first_name) SELECT c.id,_account,p.id,p.email,p.first_name FROM public.profiles p JOIN public.consents co ON co.profile_id=p.id AND co.channel='email' AND co.status='subscribed' WHERE p.account_id=_account AND p.email IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=_account AND s.email=p.email) AND (c.list_id IS NULL OR EXISTS(SELECT 1 FROM public.profile_list_members m WHERE m.list_id=c.list_id AND m.profile_id=p.id)) ON CONFLICT DO NOTHING; UPDATE public.email_bundles SET used=used+recipients WHERE account_id=_account; UPDATE public.email_campaigns SET total=recipients,status='queued',schedule_at=_schedule,updated_at=now() WHERE id=c.id; RETURN recipients; END $$; REVOKE ALL ON FUNCTION public.email_queue_campaign(uuid,uuid,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_queue_campaign(uuid,uuid,timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.email_claim_batch() RETURNS SETOF public.email_recipients LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cap public.email_provider_capacity; ids uuid[]; n integer; BEGIN INSERT INTO public.email_provider_capacity(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT * INTO cap FROM public.email_provider_capacity WHERE id=true FOR UPDATE; IF cap.day<>CURRENT_DATE THEN UPDATE public.email_provider_capacity SET day=CURRENT_DATE,used=0 WHERE id=true RETURNING * INTO cap; END IF; UPDATE public.email_recipients SET status='unconfirmed',last_error='Submission outcome unknown; not resent',updated_at=now() WHERE status='sending' AND updated_at<now()-interval '5 minutes'; SELECT array_agg(id) INTO ids FROM (SELECT r.id FROM public.email_recipients r JOIN public.email_campaigns c ON c.id=r.campaign_id JOIN public.accounts a ON a.id=r.account_id JOIN public.email_bundles b ON b.account_id=r.account_id WHERE r.status='queued' AND c.status IN ('queued','sending') AND (c.schedule_at IS NULL OR c.schedule_at<=now()) AND a.suspended_at IS NULL AND a.sending_suspended_at IS NULL AND b.status='active' AND b.period_end>now() ORDER BY r.created_at,r.id LIMIT least(25,greatest(0,cap.daily_limit-cap.used)) FOR UPDATE OF r SKIP LOCKED) q; n:=coalesce(array_length(ids,1),0); UPDATE public.email_provider_capacity SET used=used+n WHERE id=true; UPDATE public.email_campaigns SET status='sending',updated_at=now() WHERE id IN(SELECT campaign_id FROM public.email_recipients WHERE id=ANY(ids)); RETURN QUERY UPDATE public.email_recipients SET status='sending',updated_at=now() WHERE id=ANY(ids) RETURNING *; END $$; REVOKE ALL ON FUNCTION public.email_claim_batch() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_claim_batch() TO service_role;
CREATE OR REPLACE FUNCTION public.email_unsubscribe(_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.email_recipients; BEGIN SELECT * INTO r FROM public.email_recipients WHERE token=_token; IF NOT FOUND THEN RETURN; END IF; INSERT INTO public.email_suppressions(account_id,email,reason) VALUES(r.account_id,r.email,'unsubscribed') ON CONFLICT DO NOTHING; UPDATE public.consents SET status='unsubscribed',updated_at=now() WHERE profile_id=r.profile_id AND channel='email'; UPDATE public.email_recipients SET status='suppressed',updated_at=now() WHERE account_id=r.account_id AND email=r.email AND status='queued'; END $$; REVOKE ALL ON FUNCTION public.email_unsubscribe(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_unsubscribe(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.email_campaign_report(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('total',count(*),'queued',count(*) FILTER(WHERE status='queued'),'sending',count(*) FILTER(WHERE status='sending'),'accepted',count(*) FILTER(WHERE accepted_at IS NOT NULL),'delivered',count(*) FILTER(WHERE delivered_at IS NOT NULL),'bounced',count(*) FILTER(WHERE status='bounced'),'complaints',count(*) FILTER(WHERE status='complaint'),'unconfirmed',count(*) FILTER(WHERE status='unconfirmed'),'failed',count(*) FILTER(WHERE status='failed'),'suppressed',count(*) FILTER(WHERE status='suppressed'),'opened',count(*) FILTER(WHERE opened_at IS NOT NULL),'clicked',count(*) FILTER(WHERE clicked_at IS NOT NULL)) FROM public.email_recipients WHERE campaign_id=_id; $$; REVOKE ALL ON FUNCTION public.email_campaign_report(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_campaign_report(uuid) TO service_role;